import sys

def main():
    import sys
    import sys
    n = int(sys.stdin.read().strip())
    if n % 2 == 1:
        print(-1)
        return

    cycles = []

    # Create triangles for odd vertices
    for i in range(1, n-1, 2):
        cycles.append([3, i, i+1, n])

    # Create quadrilaterals for even vertices
    for i in range(1, n-2, 2):
        cycles.append([4, i, i+1, i+2, i+3])

    # Add remaining cycles for even n
    if n > 4:
        for i in range(2, n-2, 2):
            cycles.append([4, i, i+1, i+2, n])

    # Special case for n = 4
    if n == 4:
        cycles.append([4, 1, 2, 3, 4])
        cycles.append([4, 1, 3, 2, 4])

    print(len(cycles))
    for cycle in cycles:
        print(len(cycle), *cycle)

if __name__ == "__main__":
    main()
